public boolean predict(float[] features) {
    if (features.length != 5) {
        throw new IllegalArgumentException("Features must contain exactly 5 values");
    }
    INDArray input = Nd4j.create(new float[][]{features});
    INDArray output = model.output(input);
    double probability = output.getDouble(0);
    System.out.println("Prediction probability: " + probability);
    return probability > 0.5;
}

private MultiLayerNetwork createNewModel() {
    MultiLayerConfiguration config = new NeuralNetConfiguration.Builder()
            .seed(42)
            .updater(new Adam(0.001))
            .list()
            .layer(0, new DenseLayer.Builder().nIn(5).nOut(64).activation(Activation.RELU).build())
            .layer(1, new DenseLayer.Builder().nIn(64).nOut(32).activation(Activation.RELU).build())
            .layer(2, new OutputLayer.Builder(LossFunctions.LossFunction.XENT)
                    .nIn(32).nOut(1)
                    .activation(Activation.SIGMOID)
                    .build())
            .build();

    MultiLayerNetwork newModel = new MultiLayerNetwork(config);
    newModel.init();
    System.out.println("New neural network model created with seed 42");
    return newModel;
}

public void trainModel() {
    List<PlayerPerformance> players = playerPerformanceRepository.findAll();
    if (players.isEmpty()) {
        System.out.println("No training data available");
        return;
    }

    List<DataSet> dataSets = new ArrayList<>();
    for (PlayerPerformance p : players) {
        float[] features = new float[]{
            p.getAverage().floatValue(), p.getStrikeRate().floatValue(),
            p.getBowlingAverage().floatValue(), p.getEconomyRate().floatValue(),
            p.getFieldingStats().floatValue()
        };
        INDArray featureRow = Nd4j.create(features).reshape(1, 5);
        INDArray labelRow = Nd4j.create(new float[]{p.getLabel()});
        dataSets.add(new DataSet(featureRow, labelRow));
    }

    DataSet trainingData = DataSet.merge(dataSets);
    ListDataSetIterator iterator = new ListDataSetIterator(Collections.singletonList(trainingData), 32);
    model.fit(iterator);
    saveModel();
    System.out.println("Model successfully retrained with " + players.size() + " records");
}

